#include <exception>
#include <fstream>
#include <iostream>
#include <map>
#include <random>
#include <string>
#include <vector>

const int target = 20;

struct Player {
    std::string name;
    bool is_robot{false};
    int score{0};
};

class Die {
public:
    explicit Die(unsigned seed) : engine_{seed} {}
    int roll() {
        int face = faces_(engine_);
        ++counts_[face];
        return face;
    }
    const std::map<int, int>& counts() const { return counts_; }
private:
    std::mt19937 engine_;
    std::uniform_int_distribution<int> faces_{1, 6};
    std::map<int, int> counts_;
};

unsigned read_seed(int argc, char* argv[]) {
    if (argc < 2) {
        return std::random_device{}();
    }
    return static_cast<unsigned>(std::stoi(argv[1]));
}

int add_roll(int turn, int face) {
    return face == 1 ? 0 : turn + face;
}

bool robot_rolls_again(int turn, int score) {
    return turn < 10 && score + turn < target;
}

bool human_rolls_again() {
    std::string word;
    while (std::cout << "  (r)oll or (b)ank? " && std::cin >> word) {
        if (word == "r" || word == "b") {
            return word == "r";
        }
        std::cout << "  Please type r or b.\n";
    }
    return false;
}

int play_turn(const Player& p, Die& die) {
    int turn = 0;
    while (true) {
        int face = die.roll();
        turn = add_roll(turn, face);
        if (face == 1) {
            std::cout << "  rolled 1: BUST! The turn is lost.\n";
            return 0;
        }
        std::cout << "  rolled " << face << ", turn total " << turn << '\n';
        bool again = p.is_robot ? robot_rolls_again(turn, p.score)
                                : human_rolls_again();
        if (!again) {
            std::cout << "  " << p.name << " banks " << turn << '\n';
            return turn;
        }
    }
}

void save_scores(const std::vector<Player>& players) {
    std::ofstream out{"last_game.txt"};
    for (const Player& p : players) {
        out << p.name << ' ' << p.score << '\n';
    }
}

void print_report(const Die& die) {
    std::cout << "Dice report:";
    for (const auto& [face, times] : die.counts()) {
        std::cout << ' ' << face << 'x' << times;
    }
    std::cout << '\n';
}

int main(int argc, char* argv[]) {
    unsigned seed = 0;
    try {
        seed = read_seed(argc, argv);
    } catch (const std::exception&) {
        std::cerr << "bust: the seed must be a whole number, not '"
                  << argv[1] << "'\n";
        return 1;
    }
    Die die{seed};
    std::string name;
    std::cout << "BUST! First to " << target << " wins. Your name? ";
    std::getline(std::cin, name);
    std::vector<Player> players{{name}, {"Bolt", true}};

    std::size_t who = 0;
    while (true) {
        Player& p = players[who];
        std::cout << p.name << "'s turn (" << p.score << " banked)\n";
        p.score += play_turn(p, die);
        if (p.score >= target) {
            break;
        }
        who = (who + 1) % players.size();
    }
    std::cout << players[who].name << " wins with " << players[who].score << "!\n";
    save_scores(players);
    print_report(die);
}

